codeExample.bad:
/* Bad: layout only renders correctly in portrait, and shows a
   blocking message instead of reflowing when rotated to landscape */
.app {
  width: 100vw;
  height: 100vh;
}

@media (orientation: landscape) {
  .app-content {
    display: none;
  }
  .rotate-warning {
    display: flex;
    /* "Please rotate your device to portrait to continue" */
  }
}

codeExample.good:
/* Good: layout adapts to both orientations instead of blocking one */
.app {
  width: 100vw;
  height: 100vh;
  display: flex;
  flex-direction: column;
}

@media (orientation: landscape) {
  .app {
    flex-direction: row; /* reflow content for wide viewport, don't hide it */
  }
}

/* .rotate-warning is removed entirely — both orientations are supported */
